      "ur": "میرا بھروسہ صرف اللہ تعالیٰ پر ہی ہے، جو میرا اور تم سب کا پروردگار ہے جتنے بھی پاؤں دھرنے والے ہیں سب کی پیشانی وہی تھامے ہوئے ہے ۔ یقیناً میرا رب بالکل صحیح راه پر ہے۔",
      "es": "Yo me encomiendo a Dios, que es mi Señor y el suyo. Sepan que no hay criatura que se escape a Su voluntad. Mi Señor está en el camino recto [y juzga con justicia].",
      "nl": "Ik leg mijn vertrouwen in Allah, mijn Heer en jullie Heer! Er is geen levend wezen waarvan Hij de voorlok niet grijpt. Waarlijk, mijn Heer is op het rechte pad.",
      "sq": "Unë mbështetem tek Allahu, Zoti im dhe Zoti juaj. S’ka asnjë gjallesë që të mos jetë nën pushtetin e Tij. Me të vërtetë, Zoti im, është në rrugë të drejtë.",
      "bn": "আমি তো নির্ভর করি আমার ও তোমাদের রব আল্লাহ্‌র উপর; এমন কোনো জীব-জন্তু নেই, যে তাঁর পূর্ণ আয়াত্তাধীন নয়; নিশ্চয় আমার রব আছেন সরল পথে।",
      "fa": "من بر الله که پروردگار من و شماست توکل کرده‌ام. هیچ جنبنده‌ای نیست، مگر اینکه در حیطۀ قدرت و فرمانروایىِ اوست. بی‌تردید، پروردگارم بر راه راست است.",
      "ps": "بې شكه ما پر الله بروسه كړې چې زما او ستاسو رب دی، هېڅ داسې خوځېدونكى نشته چې هغه يې د پيكي (د تندي د وېښتانو) رانيوونكى نه وي، بې شكه زما رب پر سمه لار باندې دى.",
      "ckb": "بەڕاستی من پشتم بەخوا بەستووە کەپەروەردگاری من و پەروەردگاری ئێوەیشە ھیچ گیان لەبەرێک نیە لەژێر ڕکێفی خوای گەورەدا نەبێت (بگری پێشە سەریەتی) بەڕاستی پەروەردگارم لەسەر ڕێگەیەکی ڕاستە"
